# description:
# Identify the dominant cyan (color 6) bands in the grid and determine if they are oriented as rows or columns.
# In the output, color the entire row or column with cyan if it's identified as part of the dominant orientation.

def main(input_grid: np.ndarray) -> np.ndarray:
    # Count the number of cyan pixels in each row and each column
    cyan_color = Color.TEAL
    row_counts = np.sum(input_grid == cyan_color, axis=1)
    col_counts = np.sum(input_grid == cyan_color, axis=0)

    # Determine if rows or columns have more dominant cyan pixels
    if np.sum(row_counts) > np.sum(col_counts):
        # Rows are dominant
        dominant_orientation = 'row'
    else:
        # Columns are dominant
        dominant_orientation = 'column'

    # Create an output grid by coloring the dominant rows or columns with cyan
    output_grid = np.zeros_like(input_grid)

    if dominant_orientation == 'row':
        for i, count in enumerate(row_counts):
            if count > 0:
                output_grid[i, :] = cyan_color
    else:
        for j, count in enumerate(col_counts):
            if count > 0:
                output_grid[:, j] = cyan_color

    return output_grid

