    return grid

from common import *

import numpy as np
from typing import *

# concepts:
# dominant_color, orientation_detection, connected_components

# description:
# In the input grid, you will see bands of different colors. Your task is to identify the dominant cyan (color 6) bands and determine if they are oriented horizontally or vertically.
# The output should be a grid of the same size where the dominant cyan bands are highlighted in their orientation. Non-dominant colors should be black.

def main(input_grid: np.ndarray) -> np.ndarray:
    # Define the color of interest
    dominant_color = Color.TEAL  # Assuming Color.TEAL corresponds to color 6

    # Find all connected components of the dominant color
    components = find_connected_components(input_grid, background=Color.BLACK, monochromatic=True, connectivity=4)

    # Track the orientation of each component
    horizontal_count = 0
    vertical_count = 0

    for component in components:
        if np.any(component == dominant_color):
            x, y, w, h = bounding_box(component, background=Color.BLACK)
            if w > h:
                horizontal_count += 1
            else:
                vertical_count += 1

    # Determine the orientation of the dominant color
    if horizontal_count > vertical_count:
        orientation = 'horizontal'
    else:
        orientation = 'vertical'

    # Prepare the output grid
    output_grid = np.zeros_like(input_grid)

    # Highlight the dominant color bands in the determined orientation
    for component in components:
        if np.any(component == dominant_color):
            x, y, w, h = bounding_box(component, background=Color.BLACK)
            if (orientation == 'horizontal' and w > h) or (orientation == 'vertical' and h >= w):
                output_grid[component == dominant_color] = dominant_color

    return output_grid

def generate_input() -> np.ndarray:
    grid_size = 10
    grid = np.zeros((grid_size, grid_size), dtype=int)

    # Randomly generate bands of different colors
    colors = list(Color.NOT_BLACK)
    for _ in range(np.random.randint(2, 5)):
        random_color = np.random.choice(colors)
        if random_color == Color.TEAL:
            # Ensure dominant color has more bands
            for _ in range(np.random.randint(2, 4)):
                orientation = np.random.choice(['horizontal', 'vertical'])
                if orientation == 'horizontal':
                    x = np.random.randint(0, grid_size)
                    draw_line(grid, x, 0, length=grid_size, direction=(0, 1), color=random_color)
                else:
                    y = np.random.randint(0, grid_size)
                    draw_line(grid, 0, y, length=grid_size, direction=(1, 0), color=random_color)
        else:
            orientation = np.random.choice(['horizontal', 'vertical'])
            if orientation == 'horizontal':
                x = np.random.randint(0, grid_size)
                draw_line(grid, x, 0, length=grid_size, direction=(0, 1), color=random_color)
            else:
                y = np.random.randint(0, grid_size)
                draw_line(grid, 0, y, length=grid_size, direction=(1, 0), color=random_color)

    return grid
